package io.github.polestarcn.companion;
import android.content.*;
/** Display parameters only. Never creates requests or changes vehicle settings. */
public final class EffectSettings {
 public static final String[] STYLES={"c1a","c1d","c1+a","c1+d","c1+c"};
 public final boolean master,charge,air,heating,purification,absorb,fade,airAbsorb,windowGlow;public final int style,particles,lines,strength;public final float chargeSpeed,airSpeed;public final String airTint;
 public final ParticleField chargeField,climateField,cleanField;public final int trailPercent,windowRange,windowPeriod;
 public final boolean airSpheres;public final int absorbRange,topDensity,bottomDensity,leftDensity,rightDensity;
 public final boolean turbulence;public final int turbulencePercent,arcPercent,particleSizePercent,windowStrength;public final float windowSpeed;
 public EffectSettings(Context c){migrate(c);airSpheres="spheres".equals(AppPreferences.get(c,"fx_air_shape","streaks"));absorbRange=number(c,"fx_absorb_range",100,50,250);topDensity=number(c,"fx_density_top",100,0,200);bottomDensity=number(c,"fx_density_bottom",100,0,200);leftDensity=number(c,"fx_density_left",100,0,200);rightDensity=number(c,"fx_density_right",100,0,200);chargeField=new ParticleField(c,"fx_charge_field_",100,100,100,100,100);climateField=new ParticleField(c,"fx_climate_field_",absorbRange,topDensity,bottomDensity,leftDensity,rightDensity);cleanField=new ParticleField(c,"fx_clean_field_",absorbRange,topDensity,bottomDensity,leftDensity,rightDensity);trailPercent=number(c,"fx_trail_length",100,10,300);windowRange=number(c,"fx_window_range",100,25,300);windowPeriod=number(c,"fx_window_period",Math.round(700f/number(c,"fx_window_speed",100,25,300)),1,60);turbulence=AppPreferences.visible(c,"fx_turbulence",true);turbulencePercent=number(c,"fx_turbulence_percent",20,0,100);arcPercent=number(c,"fx_arc_percent",15,0,100);particleSizePercent=number(c,"fx_particle_size",100,25,300);windowStrength=number(c,"fx_window_strength",60,0,300);windowSpeed=number(c,"fx_window_speed",100,25,300)/100f;airAbsorb="absorb".equals(AppPreferences.get(c,"fx_air_direction","through"));windowGlow=AppPreferences.visible(c,"fx_window_glow",true);airTint=AppPreferences.get(c,"fx_air_tint","neutral");master=AppPreferences.visible(c,"light_effects",true);charge=AppPreferences.visible(c,"fx_charge",true);air=AppPreferences.visible(c,"fx_air",true);heating=AppPreferences.visible(c,"fx_heating",true);purification=AppPreferences.visible(c,"fx_purification",true);absorb="absorb".equals(AppPreferences.get(c,"fx_direction","up"));fade=AppPreferences.visible(c,"fx_fade",true);int s=java.util.Arrays.asList(STYLES).indexOf(AppPreferences.get(c,"fx_style","c1a"));style=Math.max(0,s);particles=number(c,"fx_particles",60,20,150);lines=number(c,"fx_lines",36,12,120);strength=number(c,"fx_strength",60,20,100);chargeSpeed=number(c,"fx_charge_speed",100,50,200)/100f;airSpeed=number(c,"fx_air_speed",100,50,200)/100f;}
 private EffectSettings(EffectSettings p,int s,boolean direction,boolean airDirection){chargeField=p.chargeField;climateField=p.climateField;cleanField=p.cleanField;trailPercent=p.trailPercent;windowRange=p.windowRange;windowPeriod=p.windowPeriod;airSpheres=p.airSpheres;absorbRange=p.absorbRange;topDensity=p.topDensity;bottomDensity=p.bottomDensity;leftDensity=p.leftDensity;rightDensity=p.rightDensity;turbulence=p.turbulence;turbulencePercent=p.turbulencePercent;arcPercent=p.arcPercent;particleSizePercent=p.particleSizePercent;windowStrength=p.windowStrength;windowSpeed=p.windowSpeed;airAbsorb=airDirection;windowGlow=p.windowGlow;airTint=p.airTint;master=p.master;charge=p.charge;air=p.air;heating=p.heating;purification=p.purification;absorb=direction;fade=p.fade;style=Math.max(0,Math.min(4,s));particles=p.particles;lines=p.lines;strength=p.strength;chargeSpeed=p.chargeSpeed;airSpeed=p.airSpeed;}
 public boolean enabled(EffectStateController.Mode mode){switch(mode){case OFF:return false;case CHARGING:return charge;case HEATING:return heating;case PURIFICATION:return purification;default:return air;}}
 EffectSettings previewCharge(int s,boolean direction){return new EffectSettings(this,s,direction,airAbsorb);}
 EffectSettings previewAir(boolean direction){return new EffectSettings(this,style,absorb,direction);}
 private static void migrate(Context c){SharedPreferences p=c.getSharedPreferences("preferences",0);if(!p.contains("fx_heating")||!p.contains("fx_purification")){SharedPreferences.Editor n=p.edit();String old=AppPreferences.visible(c,"fx_air",AppPreferences.visible(c,"effect_enabled",true))?"on":"off";if(!p.contains("fx_heating"))n.putString("fx_heating",old);if(!p.contains("fx_purification"))n.putString("fx_purification",old);n.apply();}if(p.getBoolean("fx_legacy_migrated",false))return;SharedPreferences.Editor e=p.edit().putBoolean("fx_legacy_migrated",true);
  String[][] keys={{"effect_enabled","fx_charge"},{"effect_enabled","fx_air"},{"effect_speed","fx_charge_speed"},{"effect_speed","fx_air_speed"},{"effect_particles","fx_particles"},{"effect_wind_strength","fx_strength"}};
  for(String[] key:keys)if(p.contains(key[0])&&!p.contains(key[1]))e.putString(key[1],p.getString(key[0],""));
  if(p.contains("effect_charge_style")&&!p.contains("fx_style"))e.putString("fx_style",p.getString("effect_charge_style","C1a").toLowerCase(java.util.Locale.ROOT));
  if(p.contains("effect_charge_direction")&&!p.contains("fx_direction"))e.putString("fx_direction","absorb".equals(p.getString("effect_charge_direction","rise"))?"absorb":"up");
  if(p.contains("effect_wind_count")&&!p.contains("fx_lines"))try{e.putString("fx_lines",""+(Integer.parseInt(p.getString("effect_wind_count","12"))*3));}catch(Exception ignored){}
  e.apply();
 }
 static int number(Context c,String key,int fallback,int low,int high){try{return Math.max(low,Math.min(high,Integer.parseInt(AppPreferences.get(c,key,""+fallback))));}catch(Exception e){return fallback;}}
 public static void defaults(Context c){android.content.SharedPreferences prefs=c.getSharedPreferences("preferences",0);android.content.SharedPreferences.Editor e=prefs.edit();for(String key:prefs.getAll().keySet())if(key.startsWith("fx_charge_field_")||key.startsWith("fx_climate_field_")||key.startsWith("fx_clean_field_"))e.remove(key);for(String key:new String[]{"charging_sweep_style","charging_sweep_period","charging_sweep_strength","charging_sweep_color","fx_trail_length","fx_window_range","fx_window_period","fx_air_shape","fx_absorb_range","fx_density_top","fx_density_bottom","fx_density_left","fx_density_right","light_effects","all_good_shimmer","charging_animation","page_transition","fx_charge","fx_air","fx_heating","fx_purification","fx_direction","fx_fade","fx_style","fx_particles","fx_lines","fx_strength","fx_charge_speed","fx_air_speed","fx_air_direction","fx_window_glow","fx_air_tint","fx_turbulence","fx_turbulence_percent","fx_arc_percent","fx_particle_size","fx_window_strength","fx_window_speed"})e.remove(key);e.apply();}
}
